# frozen_string_literal: true

module Railglue
  # Builds the nginx reverse proxy config that routes paths to apps.
  module Nginx
    HEADER = <<~NGINX
      # Generated by bin/railglue from railglue.yml. Do not edit.
      resolver 127.0.0.11 valid=10s ipv6=off;

      map $http_upgrade $connection_upgrade {
          default upgrade;
          ''      close;
      }
    NGINX

    SERVER_SETTINGS = <<~NGINX
      listen 80;
      client_max_body_size 100m;
      proxy_http_version 1.1;
      proxy_read_timeout 300s;
      proxy_set_header Host $http_host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_set_header Upgrade $http_upgrade;
      proxy_set_header Connection $connection_upgrade;
    NGINX

    NOT_FOUND = <<~NGINX
      location / {
          return 404;
      }
    NGINX

    module_function

    def render(config)
      "#{HEADER}\nserver {\n#{indent(server_body(config))}}\n"
    end

    def server_body(config)
      apps = config.apps.sort_by { |app| -app.mount.length }
      blocks = apps.flat_map { |app| locations(app) }
      blocks << NOT_FOUND unless config.apps.any?(&:root?)
      ([SERVER_SETTINGS] + blocks).join("\n")
    end

    def locations(app)
      return [location('/', app)] if app.root?

      [location("^~ #{app.mount}/", app), location("= #{app.mount}", app)]
    end

    def location(matcher, app)
      <<~NGINX
        location #{matcher} {
            set $upstream http://#{app.name}:#{APP_PORT};
            proxy_pass $upstream;
            add_header X-Railglue-App #{app.name} always;
        }
      NGINX
    end

    def indent(text)
      text.lines.map { |line| line.strip.empty? ? line : "    #{line}" }.join
    end
  end
end
